// Bindings added at runtime, on top of the ones generated by `wrangler types`.
// Env and Cloudflare.Env are separate interfaces, so both get the same fields.
interface Env {
  /** Injected by OAuthProvider into the default handler. */
  OAUTH_PROVIDER: import("@cloudflare/workers-oauth-provider").OAuthHelpers;
  /**
   * How /authorize is protected; set one of them as a Worker secret. They are
   * not in `secrets.required` because either one is enough.
   */
  ACCESS_AUD?: string;
  OWNER_PASSWORD?: string;
}

declare namespace Cloudflare {
  interface Env {
    OAUTH_PROVIDER: import("@cloudflare/workers-oauth-provider").OAuthHelpers;
    ACCESS_AUD?: string;
    OWNER_PASSWORD?: string;
  }
}
